insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"this_or_that_homework_q01_finish","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\this_or_that_homework.yaml","source_metadata":{}},{"key":"this_or_that_homework_q01_start","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\this_or_that_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"this_or_that_homework_q01_finish","locale":"he","line_order":0,"content":"מושלם! מחר תמסרו לאורחים את המכתב, והם יבינו כל דבר שתראו להם.","line_format":"plain_text"},{"dialogue_key":"this_or_that_homework_q01_finish","locale":"he","line_order":1,"content":"זכרו: this = הזה או הזאת, that = ההוא או ההיא, these = האלה, those = ההם. וכשלא מצביעים, the = ה' הידיעה.","line_format":"plain_text"},{"dialogue_key":"this_or_that_homework_q01_finish","locale":"he","line_order":2,"content":"כל הכבוד, יועצי הידע. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"this_or_that_homework_q01_start","locale":"he","line_order":0,"content":"יועצי הידע שלי, חזרתם! מחר מגיעים לעיירה אורחים מארץ רחוקה, והם מדברים רק אנגלית.","line_format":"plain_text"},{"dialogue_key":"this_or_that_homework_q01_start","locale":"he","line_order":1,"content":"אתם תהיו המדריכים שלהם. תראו להם את העיירה ותמסרו להם את מכתב הברכה שלי.","line_format":"plain_text"},{"dialogue_key":"this_or_that_homework_q01_start","locale":"he","line_order":2,"content":"היום אין מילים חדשות. אני רק רוצה לראות שאתם יודעים להצביע נכון באנגלית, בלי עזרה.","line_format":"plain_text"},{"dialogue_key":"this_or_that_homework_q01_start","locale":"he","line_order":3,"content":"שולחן המבחנים בפארק כבר מחכה לכם.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
